import assert from 'node:assert/strict';
import { mkdtemp, utimes, mkdir, writeFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g4-3/bot.mjs';
const { reserve } = await import(BOT);
const H = 3600e3;
const DAY = 24 * H;
const dir = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = path.join(dir, 'nested', 'state');
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);

// 1. Five allowed, sixth blocked with correct retryAt
const r1 = [];
for (let i = 0; i < 5; i++) r1.push(await reserve('alice', i % 2 ? 'sms' : 'chat', at(i * 1000)));
assert.ok(r1.every((r) => r.allowed && r.retryAt === null));
assert.equal(typeof r1[0].reason, 'string');
const b = await reserve('alice', 'push', at(5000));
assert.equal(b.allowed, false);
assert.equal(b.retryAt.getTime(), t0.getTime() + DAY); // first send + 24h
assert.match(b.reason, /5/);
console.log('blocked reason:', b.reason);

// 2. Not counted when blocked: retry before retryAt still blocked, at retryAt allowed
const early = await reserve('alice', 'sms', new Date(t0.getTime() + DAY - 1));
assert.equal(early.allowed, false);
assert.equal(early.retryAt.getTime(), t0.getTime() + DAY);
const ok = await reserve('alice', 'sms', b.retryAt);
assert.equal(ok.allowed, true);
// now alice has sends at 1s,2s,3s,4s (+ 1 at 24h) -> window at 24h+ contains 4 old + new = 5 -> next blocked
const after = await reserve('alice', 'push', new Date(t0.getTime() + DAY + 1000));
assert.equal(after.allowed, false);
// retry: 5 in window are at 2s,3s,4s,(0 excluded?) ; compute expected: window at t=24h+1s contains sends >(1s) ... 
console.log('after retry retryAt:', after.retryAt.toISOString());

// 3. Different customers independent
const bob = await reserve('bob', 'push', at(0));
assert.equal(bob.allowed, true);

// 4. Sliding window with a fresh user
const carol = 'carol-' + Math.random();
for (let i = 0; i < 5; i++) await reserve(carol, 'chat', at(i * 4 * H)); // 0,4,8,12,16h
const c6 = await reserve(carol, 'chat', at(20 * H));
assert.equal(c6.allowed, false);
assert.equal(c6.retryAt.getTime(), t0.getTime() + DAY); // oldest (0h) expires at 24h
const c7 = await reserve(carol, 'chat', at(24 * H));
assert.equal(c7.allowed, true);

// 5. In-process concurrency: 30 parallel calls for one user -> exactly 5 allowed
const dan = 'dan';
const par = await Promise.all(Array.from({ length: 30 }, () => reserve(dan, 'sms', at(0))));
assert.equal(par.filter((r) => r.allowed).length, 5);

// 6. Multi-process concurrency
const workerSrc = `
import { reserve } from ${JSON.stringify(BOT)};
const now = new Date(${t0.getTime()});
const out = [];
for (let i = 0; i < 4; i++) out.push((await reserve('erin', ['sms','push','chat'][i%3], now)).allowed);
console.log(JSON.stringify(out));
`;
await writeFile(path.join(dir, 'worker.mjs'), workerSrc);
const runWorker = () => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, [path.join(dir, 'worker.mjs')], { env: process.env });
  let o = ''; let e = '';
  p.stdout.on('data', (d) => (o += d)); p.stderr.on('data', (d) => (e += d));
  p.on('close', (code) => code === 0 ? resolve(JSON.parse(o.trim())) : reject(new Error(e)));
});
const results = await Promise.all(Array.from({ length: 8 }, runWorker));
const allowedTotal = results.flat().filter(Boolean).length;
assert.equal(allowedTotal, 5, `multi-process allowed=${allowedTotal}`);
console.log('multi-process allowed total:', allowedTotal, 'of 32 attempts');

// 7. Restart survival: new process sees erin already at 5
const again = await runWorker();
assert.deepEqual(again, [false, false, false, false]);

// 8. Stale lock from crashed process is broken
const stateDir = process.env.STATE_DIR;
const { createHash } = await import('node:crypto');
const key = createHash('sha256').update('frank').digest('hex');
const lockDir = path.join(stateDir, 'locks', `${key}.lock`);
await mkdir(lockDir, { recursive: true });
const old = new Date(Date.now() - 60_000);
await utimes(lockDir, old, old);
const f = await reserve('frank', 'push', at(0));
assert.equal(f.allowed, true);
assert.deepEqual(await readdir(path.join(stateDir, 'locks')), []);

// 9. Input validation
await assert.rejects(reserve('', 'sms', at(0)), TypeError);
await assert.rejects(reserve('x', 'email', at(0)), TypeError);
await assert.rejects(reserve('x', 'sms', new Date('nope')), TypeError);
await assert.rejects(reserve('x', 'sms', Date.now()), TypeError);

// 10. No leftover tmp files
const users = await readdir(path.join(stateDir, 'users'));
assert.ok(users.every((n) => n.endsWith('.json')), users.join(','));
console.log('ALL CHECKS PASSED');
